mapper.select:
SELECT COUNT(*) FROM posts p JOIN debate_sessions ds ON ds.id = p.debate_session_id WHERE p.is_public = TRUE
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.summary_card LIKE CONCAT('%', #{keyword}, '%') OR p.share_body LIKE CONCAT('%', #{keyword}, '%') OR ds.topic LIKE CONCAT('%', #{keyword}, '%'))
AND ds.mode = #{mode}

mapper.update:
UPDATE posts
SET is_public = #{isPublic}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM post_votes
WHERE post_id = #{postId}
  AND choice = #{choice}
